from pathlib import Path
r=Path('M:/Nexa')
def edit(name,fn):
 p=r/name;p.write_text(fn(p.read_text(encoding='utf-8-sig')),encoding='utf-8-sig')
edit('BugVisuals.cs',lambda s:s.replace('Dictionary<BugSpecies, Drawing> costumes','Dictionary<(BugSpecies,bool), Drawing> costumes').replace('Costume(BugSpecies species)','Costume(BugSpecies species, bool wings=true)').replace('costumes.TryGetValue(species,','costumes.TryGetValue((species,wings),').replace('costumes[species] = group','costumes[(species,wings)] = group').replace('dc.DrawEllipse(B("#70D8D1F0"), P("#84CC16", .6)', 'if(wings) dc.DrawEllipse(B("#70D8D1F0"), P("#84CC16", .6)').replace('dc.DrawEllipse(B("#70D8D1F0"), P("#A855F7", .6)','if(wings) dc.DrawEllipse(B("#70D8D1F0"), P("#A855F7", .6)').replace('dc.DrawLine(P("#4C666D", .4), new(-7, -5)','if(limbs) dc.DrawLine(P("#4C666D", .4), new(-7, -5)').replace('dc.DrawLine(P("#4C666D", .4), new(-7, 5)','if(limbs) dc.DrawLine(P("#4C666D", .4), new(-7, 5)'))
edit('BugAnimation.cs',lambda s:s.replace('double time)\n    {\n        if (FunctionalWings','double time, bool costume=false)\n    {\n        if (FunctionalWings').replace('BugVisuals.B(flying ? "#A0D5E3ED" : "#B8BCCDDA"), BugVisuals.P("#ACC1C9", .35)','BugVisuals.B(costume && bug.Species==BugSpecies.Flies ? "#90D8D1F0" : flying ? "#A0D5E3ED" : "#B8BCCDDA"), BugVisuals.P(costume && bug.Species==BugSpecies.Flies ? side<0 ? "#84CC16" : "#A855F7" : "#ACC1C9", .35)'))
edit('BugVisuals.Animation.cs',lambda s:s.replace('bool activeEyes=true)','bool activeEyes=true, bool drawShadow=true)').replace('dc.DrawEllipse(contactShadow, null, new(-1, 3 + (flying ? 2 : 0)), bug.Species == BugSpecies.Centipedes ? 18 : 10, flying ? 2.5 : 3.4);','if(drawShadow)DrawContactShadow(dc,bug,flying);').replace('DrawWings(dc, bug, options, time);','DrawWings(dc, bug, options, time, costume);').replace('Costume(bug.Species));','Costume(bug.Species, false));').replace('    internal static void Draw(DrawingContext','    internal static void DrawContactShadow(DrawingContext dc,BugEntity bug,bool flying)\n    {dc.DrawEllipse(contactShadow,null,new Point(-1,3),bug.Species==BugSpecies.Centipedes?18:10,flying?2.5:3.4);}\n    internal static void Draw(DrawingContext'))
edit('BugOverlay.cs',lambda s:s.replace('if(animated && bug.FlightHeight>0) p.Y-=', 'if(animated)\n            {\n                dc.PushTransform(new MatrixTransform(new Matrix(sx,0,0,sy,0,0)*new Matrix(Math.Cos(angle),Math.Sin(angle),-Math.Sin(angle),Math.Cos(angle),p.X,p.Y)));\n                BugVisuals.DrawContactShadow(dc,bug,bug.State==BugState.Flying);dc.Pop();\n            }\n            if(animated && bug.FlightHeight>0) p.Y-=').replace('Window.GetWindow(this)?.IsActive==true);','Window.GetWindow(this)?.IsActive==true,false);'))
print('Unified phantom wing costume with moving wings and grounded hover shadows.')
